class SourceTables(HTMLParser):
    def __init__(self):super().__init__();self.rows=[];self.row=None;self.cell=None;self.links=[]
    def handle_starttag(self,tag,attrs):
        if tag=='tr':self.row=[];self.links=[]
        if tag in ['td','th'] and self.row is not None:self.cell=[]
        if tag=='a' and self.row is not None:self.links += [v for k,v in attrs if k=='href']
    def handle_data(self,data):
        if self.cell is not None:self.cell.append(data)
    def handle_endtag(self,tag):
        if tag in ['td','th'] and self.cell is not None:self.row.append(''.join(self.cell).strip());self.cell=None
        if tag=='tr' and self.row is not None:self.rows.append({'cells':self.row,'links':self.links});self.row=None

